const STORAGE_KEY = 'brandpilot-ai-prototype-v2';
const PRODUCT_IMAGE = 'data:image/webp;base64,';
const $ = (selector, root = document) => root.querySelector(selector);
const $$ = (selector, root = document) => [...root.querySelectorAll(selector)];
const clamp = (value, min, max) => Math.max(min, Math.min(max, value));
const parseNumber = value => Number(String(value ?? '').replace(/[^0-9.-]/g, '')) || 0;
const money = value => new Intl.NumberFormat('th-TH', { style: 'currency', currency: 'THB', maximumFractionDigits: value < 100 ? 1 : 0 }).format(value);
const number = value => new Intl.NumberFormat('th-TH', { maximumFractionDigits: 0 }).format(value);
const percent = value => `${(value * 100).toFixed(1)}%`;

const defaults = {
  price: 79,
  cost: 31,
  budget: 180000,
  stock: 6000,
  channel: 'balanced',
  discount: 15,
  evidence: 'interviews',
  leadTime: 30,
  selectedScenario: 'balanced',
  currentQuestion: 0,
  buyerAnswers: ['', '', '', '', ''],
  buyerScores: [null, null, null, null, null],
  reflections: ['', '', '']
};

let state = loadState();
let current = 0;
let analysis = null;

const screens = $$('.screen');
const navs = $$('.nav');
const inputIds = ['price', 'cost', 'budget', 'stock', 'channel', 'discount', 'evidence', 'leadTime'];

function loadState() {
  try {
    const saved = JSON.parse(localStorage.getItem(STORAGE_KEY) || '{}');
    return { ...defaults, ...saved,
      buyerAnswers: Array.isArray(saved.buyerAnswers) ? [...defaults.buyerAnswers, ...saved.buyerAnswers].slice(0, 5) : [...defaults.buyerAnswers],
      buyerScores: Array.isArray(saved.buyerScores) ? [...defaults.buyerScores, ...saved.buyerScores].slice(0, 5) : [...defaults.buyerScores],
      reflections: Array.isArray(saved.reflections) ? [...defaults.reflections, ...saved.reflections].slice(0, 3) : [...defaults.reflections]
    };
  } catch {
    return { ...defaults, buyerAnswers: [...defaults.buyerAnswers], buyerScores: [...defaults.buyerScores], reflections: [...defaults.reflections] };
  }
}

function saveState() {
  localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
}

function syncInputsFromState() {
  for (const id of inputIds) {
    const el = $(`#${id}`);
    if (!el) continue;
    el.value = ['budget', 'stock'].includes(id) ? number(state[id]) : state[id];
  }
  state.reflections.forEach((value, index) => { $(`#reflection${index + 1}`).value = value; });
}

function readInputs() {
  state.price = parseNumber($('#price').value);
  state.cost = parseNumber($('#cost').value);
  state.budget = parseNumber($('#budget').value);
  state.stock = parseNumber($('#stock').value);
  state.channel = $('#channel').value;
  state.discount = parseNumber($('#discount').value);
  state.evidence = $('#evidence').value;
  state.leadTime = parseNumber($('#leadTime').value);
  saveState();
}

function validateInputs() {
  const errors = [];
  if (state.price <= 0) errors.push('ราคาขายต้องมากกว่า 0');
  if (state.cost < 0) errors.push('ต้นทุนต้องไม่ติดลบ');
  if (state.budget <= 0) errors.push('กรุณาระบุงบเปิดตัว');
  if (state.stock <= 0) errors.push('กรุณาระบุสต็อกเริ่มต้น');
  if (state.discount < 0 || state.discount > 60) errors.push('ส่วนลดควรอยู่ระหว่าง 0–60%');
  if (state.leadTime < 1 || state.leadTime > 365) errors.push('Lead time ควรอยู่ระหว่าง 1–365 วัน');
  $('#formError').textContent = errors.join(' · ');
  return errors.length === 0;
}

function calculateReadiness() {
  const grossMarginRate = state.price ? (state.price - state.cost) / state.price : 0;
  const budgetPerUnit = state.stock ? state.budget / state.stock : 0;
  const demand = { idea: 6, interviews: 11, pilot: 18 }[state.evidence] || 6;
  const economics = clamp(Math.round(grossMarginRate * 23), 0, 20);
  const channelBase = { online: 12, balanced: 10, modern: 7 }[state.channel] || 8;
  const channelBudgetBoost = budgetPerUnit >= 40 ? 3 : budgetPerUnit >= 25 ? 1 : 0;
  const channel = clamp(channelBase + channelBudgetBoost, 0, 15);
  const supply = state.leadTime <= 21 ? 14 : state.leadTime <= 30 ? 11 : state.leadTime <= 45 ? 8 : 5;
  const marketing = clamp(Math.round(budgetPerUnit / 3.3), 3, 15);
  const risk = clamp(9 + (state.evidence === 'pilot' ? 3 : 0) - (state.discount > 25 ? 2 : 0) - (state.cost >= state.price ? 4 : 0), 2, 15);
  const metrics = [
    { key: 'demand', label: 'หลักฐานความต้องการลูกค้า', score: demand, max: 20 },
    { key: 'economics', label: 'เศรษฐศาสตร์ต่อหน่วย', score: economics, max: 20 },
    { key: 'channel', label: 'ความเหมาะสมของช่องทาง', score: channel, max: 15 },
    { key: 'supply', label: 'ความพร้อมด้านอุปทาน', score: supply, max: 15 },
    { key: 'marketing', label: 'แผนสนับสนุนตลาด', score: marketing, max: 15 },
    { key: 'risk', label: 'ข้อมูล จริยธรรม และความเสี่ยง', score: risk, max: 15 }
  ];
  const score = metrics.reduce((sum, metric) => sum + metric.score, 0);
  const confidence = state.evidence === 'pilot' ? 'สูง' : state.evidence === 'interviews' ? 'ปานกลาง' : 'ต่ำ';
  return { score, metrics, grossMarginRate, budgetPerUnit, confidence };
}

const scenarioConfigs = [
  { id: 'conservative', number: '01', name: 'CONSERVATIVE', label: 'Online Test', subtitle: 'Online test first', gp: .23, variable: 3, discountFactor: .5, unitsFactor: .333, investmentFactor: 1 },
  { id: 'balanced', number: '02', name: 'BALANCED', label: 'Balanced Pilot', subtitle: 'Online + selected retail', gp: .22, variable: 4, discountFactor: 1, unitsFactor: 1, investmentFactor: 2 },
  { id: 'aggressive', number: '03', name: 'AGGRESSIVE', label: 'Modern Trade Rollout', subtitle: 'Broad retail rollout', gp: .35, variable: 6, discountFactor: 1.34, unitsFactor: 2.5, investmentFactor: 4.55 }
];

function calculateScenarios(readiness) {
  const scenarios = scenarioConfigs.map(config => {
    const discountRate = clamp((state.discount / 100) * config.discountFactor, 0, .45);
    const netPrice = state.price * (1 - discountRate) * (1 - config.gp);
    const contribution = netPrice - state.cost - config.variable;
    const units = Math.max(1, Math.round(state.stock * config.unitsFactor));
    const investment = state.budget * config.investmentFactor;
    const projectedContribution = contribution * units;
    const breakEvenUnits = contribution > 0 ? Math.ceil(investment / contribution) : Infinity;
    let risk = 'MEDIUM';
    if (config.id === 'conservative' && contribution > 0) risk = 'LOW';
    if (config.id === 'aggressive' || contribution <= 8 || units > state.stock * 1.2) risk = 'HIGH';
    if (contribution <= 0) risk = 'HIGH';
    return { ...config, discountRate, netPrice, contribution, units, investment, projectedContribution, breakEvenUnits, risk };
  });

  let recommended = 'balanced';
  if (readiness.score < 52 || scenarios[1].contribution < 10) recommended = 'conservative';
  if (readiness.score >= 80 && scenarios[2].contribution >= 12 && state.evidence === 'pilot') recommended = 'aggressive';
  return { scenarios, recommended };
}

function recalculate() {
  readInputs();
  const readiness = calculateReadiness();
  const scenarioResult = calculateScenarios(readiness);
  analysis = { readiness, ...scenarioResult };
  if (!scenarioConfigs.some(item => item.id === state.selectedScenario)) state.selectedScenario = scenarioResult.recommended;
  updateInputSummary();
  renderReadiness();
  renderScenarios();
  renderBuyer();
  renderRoadmap();
  renderReflectionSummary();
  saveState();
}

function updateInputSummary() {
  const gross = state.price - state.cost;
  $('#liveGross').textContent = money(gross);
  $('#liveMargin').textContent = `${state.price ? ((gross / state.price) * 100).toFixed(1) : '0.0'}% ของราคาขาย`;
  $('#heroScore').textContent = analysis.readiness.score;
  $('#inputHint').textContent = state.cost >= state.price ? 'คำเตือน: ต้นทุนสูงกว่าหรือเท่าราคาขาย' : `กำไรขั้นต้นก่อนค่าช่องทาง ${money(gross)} ต่อหน่วย`;
}

const priorityContent = {
  demand: ['พิสูจน์ความต้องการจริงก่อนเพิ่มสต็อก', 'สัมภาษณ์ลูกค้าเป้าหมายและทำ Paid Test เพื่อเก็บ Conversion กับอัตราซื้อซ้ำ'],
  economics: ['ปรับ Unit Economics ก่อนขยายช่องทาง', 'ทดสอบราคา ต้นทุน และโปรโมชั่นเพื่อให้ Contribution ต่อหน่วยยังเป็นบวก'],
  channel: ['ยืนยัน Channel–Product Fit', 'ทดลองกับช่องทางขนาดเล็ก วัด Sell-through และต้นทุนแฝงก่อนเข้าระบบใหญ่'],
  supply: ['ลดความเสี่ยงด้านสต็อกและ Lead time', 'ยืนยัน MOQ แผนเติมสินค้า และ Safety stock กับผู้ผลิตก่อนรับคำสั่งซื้อเพิ่ม'],
  marketing: ['สร้าง Demand Plan ที่วัดผลได้', 'จัดสรรงบตาม Funnel และกำหนด CAC, Conversion และจุดหยุดการใช้เงิน'],
  risk: ['กำหนด Guardrail ก่อนตัดสินใจ', 'ระบุสมมติฐาน แหล่งข้อมูล เจ้าของการตัดสินใจ และเกณฑ์ Stop / Iterate / Scale']
};

function renderReadiness() {
  const { score, metrics, confidence, grossMarginRate, budgetPerUnit } = analysis.readiness;
  $('#scoreHeadline').textContent = score;
  $('#scoreValue').textContent = score;
  $('#scoreRing').style.setProperty('--score', `${score}%`);
  $('#confidenceLabel').textContent = confidence;
  const status = score >= 80 ? ['green', 'PILOT READY'] : score >= 65 ? ['aqua', 'CONTROLLED PILOT'] : score >= 50 ? ['amber', 'NEEDS VALIDATION'] : ['red', 'HIGH UNCERTAINTY'];
  $('#readinessStatus').className = `status ${status[0]}`;
  $('#readinessStatus span').textContent = status[1];

  const weakest = [...metrics].sort((a, b) => (a.score / a.max) - (b.score / b.max))[0];
  const [title, copy] = priorityContent[weakest.key];
  $('#priorityTitle').textContent = title;
  $('#priorityCopy').textContent = copy;
  $('#metricBars').innerHTML = metrics.map(metric => `<div class="metric ${metric.key === weakest.key ? 'weak' : ''}"><span>${metric.label}</span><b>${metric.score} / ${metric.max}</b><i style="--v:${(metric.score / metric.max) * 100}%"></i></div>`).join('');

  const warnings = [];
  if (grossMarginRate < .4) warnings.push(['margin', `Gross margin ${percent(grossMarginRate)} อาจไม่พอรองรับ GP และโปรโมชั่น`]);
  else warnings.push(['good', `Gross margin ก่อนค่าช่องทาง ${percent(grossMarginRate)} มีพื้นที่ให้ทดสอบ`]);
  if (budgetPerUnit < 20) warnings.push(['budget', `งบต่อสต็อก ${money(budgetPerUnit)} ต่ำ ควรเลือก Pilot ที่แคบลง`]);
  if (state.leadTime > 45) warnings.push(['supply', `Lead time ${number(state.leadTime)} วัน เพิ่มความเสี่ยง Out-of-stock`]);
  if (state.discount > 25) warnings.push(['discount', `ส่วนลด ${state.discount}% กด Contribution ต่อหน่วยอย่างมีนัยสำคัญ`]);
  $('#warningList').innerHTML = warnings.map(([type, copyText]) => `<div class="warning ${type === 'good' ? 'good' : ''}">${copyText}</div>`).join('');
}

function renderScenarios() {
  $('#scenarioGrid').innerHTML = analysis.scenarios.map(item => {
    const selected = item.id === state.selectedScenario;
    const recommended = item.id === analysis.recommended;
    const contributionClass = item.contribution < 0 ? 'negative' : '';
    return `<article class="scenario ${selected ? 'selected' : ''} ${recommended ? 'recommended' : ''}" data-scenario="${item.id}" tabindex="0" role="button" aria-pressed="${selected}">
      <header><span>${item.number}</span><div><b>${item.name}</b><small>${item.subtitle}</small></div></header>
      <div class="key"><span>เงินลงทุนจำลอง</span><strong>${money(item.investment)}</strong></div>
      <div class="key"><span>ยอดขายสมมติ</span><strong>${number(item.units)} <small>units</small></strong></div>
      <div class="key ${contributionClass}"><span>Contribution / หน่วย</span><strong>${money(item.contribution)}</strong></div>
      <div class="key"><span>Break-even</span><strong>${Number.isFinite(item.breakEvenUnits) ? number(item.breakEvenUnits) : 'ไม่ถึงจุดคุ้มทุน'} <small>${Number.isFinite(item.breakEvenUnits) ? 'units' : ''}</small></strong></div>
      <div class="risk ${item.risk.toLowerCase()}"><i></i><span>ความเสี่ยงรวม</span><b>${item.risk}</b></div>
      <button class="scenario-select" type="button">${selected ? 'เลือกแล้ว' : 'เลือก Scenario นี้'}</button>
    </article>`;
  }).join('');

  $$('.scenario').forEach(card => {
    const choose = () => {
      state.selectedScenario = card.dataset.scenario;
      saveState();
      renderScenarios();
      renderRoadmap();
      renderReflectionSummary();
    };
    card.addEventListener('click', choose);
    card.addEventListener('keydown', event => { if (event.key === 'Enter' || event.key === ' ') { event.preventDefault(); choose(); } });
  });

  const selected = getSelectedScenario();
  $('#decisionText').textContent = selected.label;
  const reasons = {
    conservative: 'ใช้เงินน้อยที่สุด เหมาะเมื่อหลักฐานยังจำกัดหรือ Unit Economics ยังเปราะบาง',
    balanced: 'สมดุลระหว่างการเรียนรู้ เงินลงทุน และการทดสอบร้านค้าจริง',
    aggressive: 'เหมาะเมื่อมี Paid Pilot หลักฐานสูง และ Contribution รองรับค่าใช้จ่ายช่องทางใหญ่'
  };
  $('#decisionReason').textContent = reasons[selected.id];
  $('#decisionRule').textContent = selected.contribution > 0 ? `Contribution ${money(selected.contribution)}/หน่วย · ตั้งเกณฑ์ Stop หากต่ำกว่า ${money(Math.max(8, selected.contribution * .75))}` : 'Contribution ติดลบ ควรกลับไปปรับราคา ต้นทุน หรือโปรโมชั่น';
}

function getSelectedScenario() {
  return analysis.scenarios.find(item => item.id === state.selectedScenario) || analysis.scenarios[1];
}

const buyerQuestions = [
  { q: 'เหตุใดสินค้านี้จึงควรได้พื้นที่ขาย?', prompt: 'ตอบด้วยปัญหาลูกค้า หลักฐาน และความแตกต่างที่ตรวจสอบได้' },
  { q: 'หากจัดโปรโมชั่นตามแผน ธุรกิจยังมีกำไรหรือไม่?', prompt: 'อธิบายราคาสุทธิ ต้นทุน Contribution และจุดหยุดความเสี่ยง' },
  { q: 'จะทำให้สินค้าขายออกจากชั้นอย่างไร?', prompt: 'ระบุช่องทาง สื่อสนับสนุน KPI และความถี่ในการติดตาม' },
  { q: 'ถ้ายอดขายต่ำกว่าเป้า คุณจะจัดการสต็อกอย่างไร?', prompt: 'แสดง Trigger, Stock cover และแผน Iterate หรือ Stop' },
  { q: 'อีก 90 วัน Buyer ควรเห็นหลักฐานอะไร?', prompt: 'สรุปตัวเลข Go / No-go และผู้รับผิดชอบที่ชัดเจน' }
];

function renderBuyer() {
  const index = clamp(state.currentQuestion, 0, buyerQuestions.length - 1);
  const item = buyerQuestions[index];
  $('#roundLabel').textContent = `QUESTION ${index + 1} / ${buyerQuestions.length}`;
  $('#buyerQuestion').textContent = item.q;
  $('#buyerPrompt').textContent = item.prompt;
  $('#buyerAnswer').value = state.buyerAnswers[index] || '';
  updateAnswerCount();
  $('#questionNav').innerHTML = buyerQuestions.map((_, i) => `<button class="question-dot ${i === index ? 'active' : ''} ${state.buyerScores[i] ? 'scored' : ''}" data-question="${i}" type="button" aria-label="คำถาม ${i + 1}">${i + 1}</button>`).join('');
  $$('.question-dot').forEach(button => button.addEventListener('click', () => {
    state.buyerAnswers[state.currentQuestion] = $('#buyerAnswer').value;
    state.currentQuestion = Number(button.dataset.question);
    saveState();
    renderBuyer();
  }));
  const score = state.buyerScores[index];
  if (score) renderBuyerScore(score);
  else resetBuyerFeedback();
  const scored = state.buyerScores.filter(Boolean);
  $('#buyerAverage').textContent = scored.length ? `${Math.round(scored.reduce((sum, result) => sum + result.total, 0) / scored.length)}/100 จาก ${scored.length} คำถาม` : 'ยังไม่มีคะแนน';
}

function evaluateBuyerAnswer(answer) {
  const text = answer.trim();
  const length = text.length;
  const hasNumber = /\d/.test(text);
  const hasReason = /(เพราะ|ดังนั้น|เนื่องจาก|เพื่อให้|because|therefore)/i.test(text);
  const evidenceWords = /(ข้อมูล|หลักฐาน|ทดลอง|สัมภาษณ์|conversion|ซื้อซ้ำ|sell-through|pilot|test)/i.test(text);
  const economicWords = /(ราคา|ต้นทุน|กำไร|contribution|margin|gp|ส่วนลด|โปรโมชั่น|บาท|คุ้มทุน)/i.test(text);
  const channelWords = /(online|retail|modern trade|ร้าน|สาขา|buyer|ช่องทาง|ชั้นวาง|sell-through)/i.test(text);
  const monitorWords = /(รายสัปดาห์|ติดตาม|วัดผล|kpi|ยอดขาย|conversion|stock cover)/i.test(text);
  const riskWords = /(หยุด|เกณฑ์|ความเสี่ยง|stop|iterate|scale|trigger|ทบทวน|ต่ำกว่า|สูงกว่า)/i.test(text);
  const clarity = clamp(Math.round(6 + length / 24 + (hasReason ? 4 : 0)), 0, 20);
  const evidence = clamp((hasNumber ? 14 : 4) + (evidenceWords ? 12 : 3) + (length > 120 ? 4 : 0), 0, 30);
  const economics = clamp((economicWords ? 14 : 4) + (hasNumber ? 8 : 2) + (/contribution|กำไร|คุ้มทุน/i.test(text) ? 3 : 0), 0, 25);
  const channel = clamp((channelWords ? 8 : 2) + (monitorWords ? 7 : 2), 0, 15);
  const risk = clamp((riskWords ? 6 : 1) + (hasNumber ? 4 : 1), 0, 10);
  return { clarity, evidence, economics, channel, risk, total: clarity + evidence + economics + channel + risk };
}

function renderBuyerScore(score) {
  $('#buyerScore').textContent = score.total;
  const strengths = [];
  const improvements = [];
  if (score.evidence >= 22) strengths.push('ใช้หลักฐานและตัวเลขช่วยให้ตรวจสอบคำตอบได้'); else improvements.push('เพิ่มตัวเลขหรือหลักฐานจากการทดลอง');
  if (score.economics >= 18) strengths.push('เชื่อมคำตอบกับ Unit Economics'); else improvements.push('แสดงราคา ต้นทุน GP และ Contribution');
  if (score.risk >= 7) strengths.push('มีเกณฑ์ควบคุมความเสี่ยง'); else improvements.push('ระบุ Trigger สำหรับ Stop / Iterate / Scale');
  if (score.clarity < 14) improvements.push('จัดคำตอบเป็น เหตุผล–หลักฐาน–การตัดสินใจ');
  $('#buyerStrength').textContent = strengths.length ? strengths.join(' · ') : 'เริ่มตอบตรงคำถามแล้ว';
  $('#buyerImprove').textContent = improvements.length ? improvements.join(' · ') : 'คำตอบครบองค์ประกอบ ลองทำให้กระชับขึ้น';
  const rubric = [
    ['CLARITY', score.clarity, 20], ['EVIDENCE', score.evidence, 30], ['ECONOMICS', score.economics, 25], ['CHANNEL', score.channel, 15], ['RISK', score.risk, 10]
  ];
  $('#rubric').innerHTML = rubric.map(([label, value, max]) => `<span class="${value / max >= .7 ? 'good' : ''}">${label} ${value}/${max}</span>`).join('');
}

function resetBuyerFeedback() {
  $('#buyerScore').textContent = '—';
  $('#buyerStrength').textContent = 'พิมพ์คำตอบแล้วกดประเมิน';
  $('#buyerImprove').textContent = 'ระบบจะประเมินด้วย Rubric ที่เปิดเผยได้';
  $('#rubric').innerHTML = ['CLARITY 0/20', 'EVIDENCE 0/30', 'ECONOMICS 0/25', 'CHANNEL 0/15', 'RISK 0/10'].map(label => `<span>${label}</span>`).join('');
}

function updateAnswerCount() {
  $('#answerCount').textContent = `${$('#buyerAnswer').value.length} ตัวอักษร`;
}

const roadmapTemplates = {
  conservative: [
    ['30', 'Discover', ['สัมภาษณ์ลูกค้าเป้าหมาย 12–15 คน', 'ทดสอบข้อความคุณค่า 2 แบบ', 'ยืนยันต้นทุนและ MOQ'], 'มี Problem–Solution Evidence'],
    ['60', 'Online Test', ['เปิดขายชุดเล็กใน Online', 'ทดสอบราคา 2 ระดับ', 'ติดตาม Conversion และซื้อซ้ำ'], 'ซื้อซ้ำ ≥ 20%'],
    ['90', 'Decide', ['สรุป CAC และ Contribution', 'แก้ Product / Offer', 'ตัดสินใจ Pilot หรือ Stop'], 'Evidence before retail']
  ],
  balanced: [
    ['30', 'Validate', ['สัมภาษณ์ลูกค้าเป้าหมาย 12 คน', 'ทดสอบราคาและ Promotion', 'ยืนยันต้นทุนและ MOQ'], 'ซื้อซ้ำ ≥ 25%'],
    ['60', 'Pilot', ['ขาย Online + ร้านคัดเลือก', 'ติดตามกำไรแยกช่องทาง', 'วัด Sell-through รายสัปดาห์'], 'Contribution ผ่านเกณฑ์'],
    ['90', 'Decide', ['ซ้อม Pitch กับ Virtual Buyer', 'สรุป Stock cover', 'ตัดสินใจ Scale / Iterate / Stop'], 'Evidence before scale']
  ],
  aggressive: [
    ['30', 'Retail Ready', ['ยืนยัน Forecast และ Service level', 'ล็อกแผนผลิตและ Safety stock', 'เตรียม Trade story'], 'Fill rate ≥ 95%'],
    ['60', 'Launch', ['เปิดตัวตาม Cluster ร้าน', 'ติดตาม Sell-through รายวัน', 'โยกงบตามประสิทธิภาพ'], 'On-shelf + Velocity'],
    ['90', 'Optimize', ['ทบทวน GP และ Promotion', 'ตัด SKU / Store ที่ไม่ผ่าน', 'ขยายเฉพาะ Cluster ที่ชนะ'], 'Profitable scale']
  ]
};

function renderRoadmap() {
  const selected = getSelectedScenario();
  const roadmap = roadmapTemplates[selected.id];
  $('#roadmapScenario').textContent = selected.label.toUpperCase();
  $('#roadmap').innerHTML = roadmap.map(([day, title, tasks, gate], index) => `<article><div class="day"><strong>${day}</strong><span>DAYS</span></div><h3>${title}</h3><ul>${tasks.map(task => `<li>${task}</li>`).join('')}</ul><footer><b>GATE 0${index + 1}</b><span>${gate}</span></footer></article>`).join('');
  $('#roadmapBudget').textContent = money(selected.investment);
  $('#roadmapContribution').textContent = `${money(selected.contribution)}/หน่วย`;
  $('#roadmapGate').textContent = selected.contribution > 0 ? 'Pilot / Iterate / Stop' : 'Fix Economics / Stop';
}

function renderReflectionSummary() {
  const selected = getSelectedScenario();
  $('#reflectionScenario').textContent = selected.label;
  $('#reflectionScore').textContent = `Readiness ${analysis.readiness.score}/100 · Contribution ${money(selected.contribution)}/หน่วย`;
}

function go(index) {
  current = clamp(index, 0, screens.length - 1);
  screens.forEach((screen, i) => {
    screen.classList.toggle('active', i === current);
    screen.setAttribute('aria-hidden', i === current ? 'false' : 'true');
    if (i === current) screen.scrollTop = 0;
  });
  navs.forEach((nav, i) => {
    nav.classList.toggle('active', i === current);
    if (i === current) nav.setAttribute('aria-current', 'step'); else nav.removeAttribute('aria-current');
  });
  $('#progressBar').style.width = `${((current + 1) / screens.length) * 100}%`;
  if (current >= 2) recalculate();
}

function resetSimulation() {
  const confirmed = window.confirm('เริ่มรอบใหม่และล้างข้อมูลที่บันทึกไว้ในเบราว์เซอร์หรือไม่?');
  if (!confirmed) return;
  localStorage.removeItem(STORAGE_KEY);
  state = { ...defaults, buyerAnswers: [...defaults.buyerAnswers], buyerScores: [...defaults.buyerScores], reflections: [...defaults.reflections] };
  syncInputsFromState();
  recalculate();
  go(0);
}

function downloadSummary() {
  state.reflections = [1, 2, 3].map(i => $(`#reflection${i}`).value.trim());
  saveState();
  const selected = getSelectedScenario();
  const scored = state.buyerScores.filter(Boolean);
  const buyerAverage = scored.length ? Math.round(scored.reduce((sum, item) => sum + item.total, 0) / scored.length) : 0;
  const lines = [
    'BRANDPILOT AI — Simulation Summary',
    `Generated: ${new Date().toLocaleString('th-TH')}`,
    '',
    'INPUT',
    `Retail price: ${money(state.price)}`,
    `Unit cost: ${money(state.cost)}`,
    `Launch budget: ${money(state.budget)}`,
    `Opening stock: ${number(state.stock)} units`,
    `Maximum discount: ${state.discount}%`,
    '',
    'DECISION',
    `Readiness: ${analysis.readiness.score}/100`,
    `Scenario: ${selected.label}`,
    `Contribution: ${money(selected.contribution)}/unit`,
    `Buyer average: ${buyerAverage || 'Not evaluated'}`,
    '',
    'REFLECTION',
    `1. ${state.reflections[0] || '-'}`,
    `2. ${state.reflections[1] || '-'}`,
    `3. ${state.reflections[2] || '-'}`,
    '',
    'Disclaimer: This prototype uses fictional data and simulation assumptions for learning only.'
  ];
  const blob = new Blob([lines.join('\n')], { type: 'text/plain;charset=utf-8' });
  const url = URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.href = url;
  link.download = 'BRANDPILOT_AI_Simulation_Summary.txt';
  link.click();
  URL.revokeObjectURL(url);
}

function bindEvents() {
  navs.forEach((nav, index) => nav.addEventListener('click', () => go(index)));
  $$('[data-next]').forEach(button => button.addEventListener('click', () => go(current + 1)));
  $$('[data-back]').forEach(button => button.addEventListener('click', () => go(current - 1)));
  $('#analyze').addEventListener('click', () => { readInputs(); recalculate(); if (validateInputs()) go(2); });
  inputIds.forEach(id => {
    const el = $(`#${id}`);
    el.addEventListener('input', () => { readInputs(); recalculate(); validateInputs(); });
    el.addEventListener('change', () => { readInputs(); recalculate(); validateInputs(); });
    if (['budget', 'stock'].includes(id)) el.addEventListener('blur', () => { el.value = number(parseNumber(el.value)); });
  });
  $('#formulaToggle').addEventListener('click', event => {
    const details = $('#formulaDetails');
    const open = details.hidden;
    details.hidden = !open;
    event.currentTarget.setAttribute('aria-expanded', String(open));
    event.currentTarget.textContent = open ? 'ซ่อนวิธีคิดคะแนน' : 'ดูวิธีคิดคะแนน';
  });
  $('#buyerAnswer').addEventListener('input', event => {
    state.buyerAnswers[state.currentQuestion] = event.target.value;
    saveState();
    updateAnswerCount();
  });
  $('#evaluate').addEventListener('click', () => {
    const answer = $('#buyerAnswer').value.trim();
    if (answer.length < 20) {
      $('#buyerImprove').textContent = 'กรุณาอธิบายอย่างน้อย 20 ตัวอักษร เพื่อให้ Rubric ประเมินได้';
      return;
    }
    const score = evaluateBuyerAnswer(answer);
    state.buyerAnswers[state.currentQuestion] = answer;
    state.buyerScores[state.currentQuestion] = score;
    saveState();
    renderBuyer();
  });
  $('#saveReflection').addEventListener('click', () => {
    state.reflections = [1, 2, 3].map(i => $(`#reflection${i}`).value.trim());
    saveState();
    const complete = $('#completeState');
    complete.classList.add('saved');
    $('b', complete).textContent = 'REFLECTION SAVED';
    $('span', complete).textContent = 'บันทึกสำเร็จในเบราว์เซอร์เครื่องนี้';
  });
  $('#downloadSummary').addEventListener('click', downloadSummary);
  $('#restart').addEventListener('click', resetSimulation);
  $('#resetTop').addEventListener('click', resetSimulation);
  $('#whyRecommended').addEventListener('click', () => {
    const selected = getSelectedScenario();
    const recommended = analysis.scenarios.find(item => item.id === analysis.recommended);
    $('#reasonDialogCopy').textContent = selected.id === analysis.recommended
      ? `${selected.label} เหมาะกับ Readiness ${analysis.readiness.score}/100 และให้ Contribution ${money(selected.contribution)}/หน่วย ภายใต้ความเสี่ยง ${selected.risk}. ระบบใช้หลักฐาน ความพร้อม และ Unit Economics ประกอบกัน แต่ผู้ใช้ยังเป็นผู้ตัดสินใจสุดท้าย`
      : `คุณเลือก ${selected.label} ขณะที่ระบบแนะนำ ${recommended.label}. ตัวเลือกของคุณให้ Contribution ${money(selected.contribution)}/หน่วยและมีความเสี่ยง ${selected.risk}. ควรกำหนดเกณฑ์ Stop ให้ชัดเจนก่อนทดลอง`;
    $('#reasonDialog').showModal();
  });
  $('#closeDialog').addEventListener('click', () => $('#reasonDialog').close());
  document.addEventListener('keydown', event => {
    if (event.target.matches('input,textarea,select')) return;
    if (event.key === 'ArrowRight') go(current + 1);
    if (event.key === 'ArrowLeft') go(current - 1);
  });
}

$$('[data-product-image]').forEach(image => { image.src = PRODUCT_IMAGE; });
syncInputsFromState();
bindEvents();
recalculate();
go(0);

window.brandpilot = { go, recalculate, getState: () => ({ ...state }), getAnalysis: () => analysis };
